void ekf_integrate(float X_[N_STATES], float U[N_INPUTS], float dt) {
    // INTEGRATION STEP X_integrate = ...
    static float X_integrate[N_STATES];
    tmp[0] = powf(X[6], 2);
    tmp[1] = powf(X[7], 2);
    tmp[2] = powf(X[8], 2);
    tmp[3] = powf(X[9], 2);
    tmp[4] = tmp[0] + tmp[1] + tmp[2] + tmp[3];
    tmp[5] = powf(tmp[4], -1.0/2.0);
    tmp[6] = X[6]*tmp[5];
    tmp[7] = X[3]*tmp[6];
    tmp[8] = X[8]*tmp[5];
    tmp[9] = X[5]*tmp[8];
    tmp[10] = X[4]*tmp[5];
    tmp[11] = X[9]*tmp[10];
    tmp[12] = -tmp[11] + tmp[7] + tmp[9];
    tmp[13] = -X[3]*tmp[8] + X[5]*tmp[6] + X[7]*tmp[10];
    tmp[14] = X[9]*tmp[5];
    tmp[15] = X[7]*tmp[5];
    tmp[16] = X[3]*tmp[14] + X[4]*tmp[6] - X[5]*tmp[15];
    tmp[17] = -X[3]*tmp[15] - X[4]*tmp[8] - X[5]*tmp[14];
    tmp[18] = U[5] - X[15];
    tmp[19] = U[4] - X[14];
    tmp[20] = 1.0/tmp[4];
    tmp[21] = 19.620000000000001*tmp[20];
    tmp[22] = X[8]*tmp[21];
    tmp[23] = X[7]*tmp[21];
    tmp[24] = U[3] - X[13];
    tmp[25] = 9.8100000000000005*tmp[20];
    tmp[26] = 0.5*tmp[24];
    tmp[27] = 0.5*X[8];
    tmp[28] = 0.5*X[9];
    tmp[29] = 0.5*X[6];
    tmp[30] = 0.5*X[7];
    X_integrate[0] = X[0] + dt*(tmp[12]*tmp[6] + tmp[13]*tmp[8] - tmp[14]*tmp[16] - tmp[15]*tmp[17]);
    X_integrate[1] = X[1] + dt*(-tmp[13]*tmp[15] - tmp[14]*(tmp[11] - tmp[7] - tmp[9]) + tmp[16]*tmp[6] - tmp[17]*tmp[8]);
    X_integrate[2] = X[2] + dt*(-tmp[12]*tmp[8] + tmp[13]*tmp[6] - tmp[14]*tmp[17] + tmp[15]*tmp[16]);
    X_integrate[3] = X[3] + dt*(U[0] - X[10] + X[4]*tmp[18] - X[5]*tmp[19] - X[6]*tmp[22] + X[9]*tmp[23]);
    X_integrate[4] = X[4] + dt*(U[1] - X[11] - X[3]*tmp[18] + X[5]*tmp[24] + X[6]*tmp[23] + X[9]*tmp[22]);
    X_integrate[5] = X[5] + dt*(U[2] - X[12] + X[3]*tmp[19] - X[4]*tmp[24] + tmp[0]*tmp[25] - tmp[1]*tmp[25] - tmp[25]*tmp[2] + tmp[25]*tmp[3]);
    X_integrate[6] = X[6] + dt*(-X[7]*tmp[26] - tmp[18]*tmp[28] - tmp[19]*tmp[27]);
    X_integrate[7] = X[7] + dt*(X[6]*tmp[26] + tmp[18]*tmp[27] - tmp[19]*tmp[28]);
    X_integrate[8] = X[8] + dt*(X[9]*tmp[26] - tmp[18]*tmp[30] + tmp[19]*tmp[29]);
    X_integrate[9] = X[9] + dt*(-X[8]*tmp[26] + tmp[18]*tmp[29] + tmp[19]*tmp[30]);
    X_integrate[10] = X[10];
    X_integrate[11] = X[11];
    X_integrate[12] = X[12];
    X_integrate[13] = X[13];
    X_integrate[14] = X[14];
    X_integrate[15] = X[15];
    X_integrate[16] = X[16];
    X_integrate[17] = X[17];
    X_integrate[18] = X[18];
    X_integrate[19] = X[19];
    X_integrate[20] = X[20];
    X_integrate[21] = X[21];
    X_integrate[22] = X[22];
    X_integrate[23] = X[23];
    X_integrate[24] = X[24];
    X_integrate[25] = X[25];

    // fill in X_
    for (int i=0; i<N_STATES; i++) {
        X_[i] = X_integrate[i];
    }
}


