void ekf_update_pos(const float Z[N_MEASUREMENTS_POS], int num_iter) {
    // parameters
    
    // gain matrices all matrices col major
    static float h[N_MEASUREMENTS_POS];
    static float H[N_MEASUREMENTS_POS*N_STATES];
    static float HP[N_MEASUREMENTS_POS*N_STATES];
    static float S[N_MEASUREMENTS_POS*N_MEASUREMENTS_POS];
    static float S_chol[N_MEASUREMENTS_POS*N_MEASUREMENTS_POS];
    static float S_iDiag[N_MEASUREMENTS_POS];
    static float K[N_STATES*N_MEASUREMENTS_POS];

    // renaming
    float *R = ekf_R_pos;

    // iterated ekf
    for (int iter = 0; iter < num_iter; iter++) {
        // prepare gain calculation
        // compute H
        ekf_H_pos(H);

        // compute h
        ekf_h_pos(h);

        // compute HP
        for (int i = 0; i < N_MEASUREMENTS_POS; i++) {
            for (int j = 0; j < N_STATES; j++) {
                HP[i+j*N_MEASUREMENTS_POS] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    HP[i+j*N_MEASUREMENTS_POS] += H[i+k*N_MEASUREMENTS_POS] * ekf_P_index(k,j);
                }
            }
        }

        // compute S = H*P*H' + R
        for (int i = 0; i < N_MEASUREMENTS_POS; i++) {
            for (int j = 0; j < N_MEASUREMENTS_POS; j++) {
                S[i+j*N_MEASUREMENTS_POS] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    S[i+j*N_MEASUREMENTS_POS] += H[i+k*N_MEASUREMENTS_POS] * HP[j+k*N_MEASUREMENTS_POS];
                }
            }
            S[i+i*N_MEASUREMENTS_POS] += R[i];
        }

        // we have symmetric S and PHT in col major.
        // Solve K as K^T = invS * H*P, as we have columns of HP. We solve columns of K^T, which are actually rows of K
        // full state kalman update
        chol(S_chol, S, S_iDiag, N_MEASUREMENTS_POS);
        for (int i = 0; i < N_STATES; i++) {
            float k_row[N_MEASUREMENTS_POS];
            chol_solve(S_chol, S_iDiag, N_MEASUREMENTS_POS, (HP+(i*N_MEASUREMENTS_POS)), k_row);
            for (int j = 0; j < N_MEASUREMENTS_POS; j++) {
                K[i + j*N_STATES] = k_row[j];
            }
        }

        // UPDATE STEP X_new = ...
        for (int i = 0; i < N_STATES; i++) {
            X_new[i] = X[i];
            for (int j = 0; j < N_MEASUREMENTS_POS; j++) {
                X_new[i] += K[i + j*N_STATES] * (Z[j] - h[j]);
            }
        }   

        // swap X, X_new
        swap_ptr = X;
        X = X_new;
        X_new = swap_ptr;

        // normalize state
        ekf_normalize();
    }

    // UPDATE STEP P_new = (I - K*H)*P
    for (int i = 0; i < N_STATES; i++) {
        for (int j = 0; j <= i; j++) { // only lower diagonal
            P_new[i*(i+1)/2 + j] = P[i*(i+1)/2 + j];
            for (int k = 0; k < N_MEASUREMENTS_POS; k++) {
                P_new[i*(i+1)/2 + j] -= K[i + k*N_STATES] * HP[k + j*N_MEASUREMENTS_POS];
            }
        }
    }

    // swap P, P_new pointers
    swap_ptr = P;
    P = P_new;
    P_new = swap_ptr;
}
