void ekf_h_points_1(float h[N_MEASUREMENTS_POINTS_1], const float param[3]) {
    // parameters
    float p3d0_x = param[0];
    float p3d0_y = param[1];
    float p3d0_z = param[2];

    // h
    tmp[0] = sinf(X[20]);
    tmp[1] = -X[0] + p3d0_x;
    tmp[2] = powf(powf(X[6], 2) + powf(X[7], 2) + powf(X[8], 2) + powf(X[9], 2), -1.0/2.0);
    tmp[3] = X[7]*tmp[2];
    tmp[4] = -X[1] + p3d0_y;
    tmp[5] = X[8]*tmp[2];
    tmp[6] = -X[2] + p3d0_z;
    tmp[7] = X[9]*tmp[2];
    tmp[8] = tmp[1]*tmp[3] + tmp[4]*tmp[5] + tmp[6]*tmp[7];
    tmp[9] = X[6]*tmp[2];
    tmp[10] = tmp[2]*tmp[4];
    tmp[11] = -X[7]*tmp[10] + tmp[1]*tmp[5] + tmp[6]*tmp[9];
    tmp[12] = tmp[1]*tmp[9];
    tmp[13] = X[9]*tmp[10];
    tmp[14] = tmp[5]*tmp[6];
    tmp[15] = tmp[12] + tmp[13] - tmp[14];
    tmp[16] = -tmp[1]*tmp[7] + tmp[3]*tmp[6] + tmp[4]*tmp[9];
    tmp[17] = -X[18] + tmp[11]*tmp[9] + tmp[15]*tmp[5] - tmp[16]*tmp[3] + tmp[7]*tmp[8];
    tmp[18] = cosf(X[20]);
    tmp[19] = cosf(X[21]);
    tmp[20] = -X[16] - tmp[11]*tmp[5] + tmp[15]*tmp[9] + tmp[16]*tmp[7] + tmp[3]*tmp[8];
    tmp[21] = sinf(X[21]);
    tmp[22] = -X[17] + tmp[11]*tmp[3] + tmp[16]*tmp[9] + tmp[5]*tmp[8] + tmp[7]*(-tmp[12] - tmp[13] + tmp[14]);
    tmp[23] = 1.0/(-tmp[0]*tmp[17] + tmp[18]*tmp[19]*tmp[20] + tmp[18]*tmp[21]*tmp[22]);
    tmp[24] = sinf(X[19]);
    tmp[25] = tmp[17]*tmp[18];
    tmp[26] = cosf(X[19]);
    tmp[27] = tmp[19]*tmp[26];
    tmp[28] = tmp[21]*tmp[24];
    tmp[29] = tmp[21]*tmp[26];
    tmp[30] = tmp[19]*tmp[24];
    h[0] = X[22]*tmp[23]*(tmp[20]*(tmp[0]*tmp[30] - tmp[29]) + tmp[22]*(tmp[0]*tmp[28] + tmp[27]) + tmp[24]*tmp[25]) + X[24];
    h[1] = X[23]*tmp[23]*(tmp[20]*(tmp[0]*tmp[27] + tmp[28]) + tmp[22]*(tmp[0]*tmp[29] - tmp[30]) + tmp[25]*tmp[26]) + X[25];
}

