    tmp[22] = -X[16];
    tmp[23] = tmp[11]*tmp[20] + tmp[12]*tmp[5] + tmp[13]*tmp[19] - tmp[15]*tmp[8] + tmp[22];
    tmp[24] = cosf(X[21]);
    tmp[25] = cosf(X[20]);
    tmp[26] = tmp[24]*tmp[25];
    tmp[27] = -X[17];
    tmp[28] = tmp[11]*(-tmp[16] - tmp[17] + tmp[18]) + tmp[12]*tmp[8] + tmp[13]*tmp[20] + tmp[15]*tmp[5] + tmp[27];
    tmp[29] = sinf(X[21]);
    tmp[30] = tmp[25]*tmp[29];
    tmp[31] = 1.0/(-tmp[0]*tmp[21] + tmp[23]*tmp[26] + tmp[28]*tmp[30]);
    tmp[32] = sinf(X[19]);
