    tmp[31] = 1.0/(-tmp[0]*tmp[21] + tmp[23]*tmp[26] + tmp[28]*tmp[30]);
    tmp[32] = sinf(X[19]);
    tmp[33] = tmp[21]*tmp[25];
    tmp[34] = cosf(X[19]);
    tmp[35] = tmp[24]*tmp[34];
    tmp[36] = tmp[29]*tmp[32];
    tmp[37] = tmp[0]*tmp[36] + tmp[35];
