    float p3d12_y = param[37];
    float p3d12_z = param[38];
    float p3d13_x = param[39];
    float p3d13_y = param[40];
    float p3d13_z = param[41];
    float p3d14_x = param[42];
    float p3d14_y = param[43];
    float p3d14_z = param[44];

    // h
    tmp[0] = sinf(X[20]);
    tmp[1] = -X[18];
    tmp[2] = -X[0];
    tmp[3] = p3d0_x + tmp[2];
    tmp[4] = powf(powf(X[6], 2) + powf(X[7], 2) + powf(X[8], 2) + powf(X[9], 2), -1.0/2.0);
    tmp[5] = X[7]*tmp[4];
    tmp[6] = -X[1];
    tmp[7] = p3d0_y + tmp[6];
    tmp[8] = X[8]*tmp[4];
    tmp[9] = -X[2];
    tmp[10] = p3d0_z + tmp[9];
    tmp[11] = X[9]*tmp[4];
    tmp[12] = tmp[10]*tmp[11] + tmp[3]*tmp[5] + tmp[7]*tmp[8];
    tmp[13] = X[6]*tmp[4];
    tmp[14] = tmp[4]*tmp[7];
    tmp[15] = -X[7]*tmp[14] + tmp[10]*tmp[13] + tmp[3]*tmp[8];
    tmp[16] = tmp[13]*tmp[3];
    tmp[17] = X[9]*tmp[14];
    tmp[18] = tmp[10]*tmp[8];
    tmp[19] = tmp[16] + tmp[17] - tmp[18];
    tmp[20] = tmp[10]*tmp[5] - tmp[11]*tmp[3] + tmp[13]*tmp[7];
    tmp[21] = tmp[11]*tmp[12] + tmp[13]*tmp[15] + tmp[19]*tmp[8] + tmp[1] - tmp[20]*tmp[5];
    tmp[22] = -X[16];
    tmp[23] = tmp[11]*tmp[20] + tmp[12]*tmp[5] + tmp[13]*tmp[19] - tmp[15]*tmp[8] + tmp[22];
    tmp[24] = cosf(X[21]);
    tmp[25] = cosf(X[20]);
    tmp[26] = tmp[24]*tmp[25];
    tmp[27] = -X[17];
    tmp[28] = tmp[11]*(-tmp[16] - tmp[17] + tmp[18]) + tmp[12]*tmp[8] + tmp[13]*tmp[20] + tmp[15]*tmp[5] + tmp[27];
    tmp[29] = sinf(X[21]);
    tmp[30] = tmp[25]*tmp[29];
    tmp[31] = 1.0/(-tmp[0]*tmp[21] + tmp[23]*tmp[26] + tmp[28]*tmp[30]);
    tmp[32] = sinf(X[19]);
    tmp[33] = tmp[21]*tmp[25];
    tmp[34] = cosf(X[19]);
    tmp[35] = tmp[24]*tmp[34];
    tmp[36] = tmp[29]*tmp[32];
    tmp[37] = tmp[0]*tmp[36] + tmp[35];
    tmp[38] = tmp[29]*tmp[34];
    tmp[39] = tmp[24]*tmp[32];
    tmp[40] = tmp[0]*tmp[39] - tmp[38];
    tmp[41] = tmp[0]*tmp[35] + tmp[36];
    tmp[42] = tmp[0]*tmp[38] - tmp[39];
    tmp[43] = p3d1_x + tmp[2];
    tmp[44] = p3d1_y + tmp[6];
    tmp[45] = p3d1_z + tmp[9];
    tmp[46] = tmp[11]*tmp[45] + tmp[43]*tmp[5] + tmp[44]*tmp[8];
    tmp[47] = tmp[13]*tmp[45] + tmp[43]*tmp[8] - tmp[44]*tmp[5];
    tmp[48] = tmp[13]*tmp[43];
    tmp[49] = tmp[11]*tmp[44];
    tmp[50] = tmp[45]*tmp[8];
    tmp[51] = tmp[48] + tmp[49] - tmp[50];
    tmp[52] = -tmp[11]*tmp[43] + tmp[13]*tmp[44] + tmp[45]*tmp[5];
    tmp[53] = tmp[11]*tmp[46] + tmp[13]*tmp[47] + tmp[1] + tmp[51]*tmp[8] - tmp[52]*tmp[5];
    tmp[54] = tmp[11]*tmp[52] + tmp[13]*tmp[51] + tmp[22] + tmp[46]*tmp[5] - tmp[47]*tmp[8];
    tmp[55] = tmp[11]*(-tmp[48] - tmp[49] + tmp[50]) + tmp[13]*tmp[52] + tmp[27] + tmp[46]*tmp[8] + tmp[47]*tmp[5];
    tmp[56] = 1.0/(-tmp[0]*tmp[53] + tmp[26]*tmp[54] + tmp[30]*tmp[55]);
    tmp[57] = tmp[25]*tmp[53];
    tmp[58] = p3d2_x + tmp[2];
    tmp[59] = p3d2_y + tmp[6];
    tmp[60] = p3d2_z + tmp[9];
    tmp[61] = tmp[11]*tmp[60] + tmp[58]*tmp[5] + tmp[59]*tmp[8];
    tmp[62] = tmp[13]*tmp[60] + tmp[58]*tmp[8] - tmp[59]*tmp[5];
    tmp[63] = tmp[13]*tmp[58];
    tmp[64] = tmp[11]*tmp[59];
    tmp[65] = tmp[60]*tmp[8];
    tmp[66] = tmp[63] + tmp[64] - tmp[65];
    tmp[67] = -tmp[11]*tmp[58] + tmp[13]*tmp[59] + tmp[5]*tmp[60];
    tmp[68] = tmp[11]*tmp[61] + tmp[13]*tmp[62] + tmp[1] - tmp[5]*tmp[67] + tmp[66]*tmp[8];
    tmp[69] = tmp[11]*tmp[67] + tmp[13]*tmp[66] + tmp[22] + tmp[5]*tmp[61] - tmp[62]*tmp[8];
    tmp[70] = tmp[11]*(-tmp[63] - tmp[64] + tmp[65]) + tmp[13]*tmp[67] + tmp[27] + tmp[5]*tmp[62] + tmp[61]*tmp[8];
    tmp[71] = 1.0/(-tmp[0]*tmp[68] + tmp[26]*tmp[69] + tmp[30]*tmp[70]);
    tmp[72] = tmp[25]*tmp[68];
    tmp[73] = p3d3_x + tmp[2];
    tmp[74] = p3d3_y + tmp[6];
    tmp[75] = p3d3_z + tmp[9];
    tmp[76] = tmp[11]*tmp[75] + tmp[5]*tmp[73] + tmp[74]*tmp[8];
    tmp[77] = tmp[13]*tmp[75] - tmp[5]*tmp[74] + tmp[73]*tmp[8];
    tmp[78] = tmp[13]*tmp[73];
    tmp[79] = tmp[11]*tmp[74];
    tmp[80] = tmp[75]*tmp[8];
    tmp[81] = tmp[78] + tmp[79] - tmp[80];
    tmp[82] = -tmp[11]*tmp[73] + tmp[13]*tmp[74] + tmp[5]*tmp[75];
    tmp[83] = tmp[11]*tmp[76] + tmp[13]*tmp[77] + tmp[1] - tmp[5]*tmp[82] + tmp[81]*tmp[8];
    tmp[84] = tmp[11]*tmp[82] + tmp[13]*tmp[81] + tmp[22] + tmp[5]*tmp[76] - tmp[77]*tmp[8];
    tmp[85] = tmp[11]*(-tmp[78] - tmp[79] + tmp[80]) + tmp[13]*tmp[82] + tmp[27] + tmp[5]*tmp[77] + tmp[76]*tmp[8];
    tmp[86] = 1.0/(-tmp[0]*tmp[83] + tmp[26]*tmp[84] + tmp[30]*tmp[85]);
    tmp[87] = tmp[25]*tmp[83];
    tmp[88] = p3d4_x + tmp[2];
    tmp[89] = p3d4_y + tmp[6];
    tmp[90] = p3d4_z + tmp[9];
    tmp[91] = tmp[11]*tmp[90] + tmp[5]*tmp[88] + tmp[89]*tmp[8];
    tmp[92] = tmp[13]*tmp[90] - tmp[5]*tmp[89] + tmp[88]*tmp[8];
    tmp[93] = tmp[13]*tmp[88];
    tmp[94] = tmp[11]*tmp[89];
    tmp[95] = tmp[8]*tmp[90];
